void dei_rs_running( void )
{
	#define EVT_MSK_RUNTIME (1<<DEI_RS_EVT_TRANSMITTER_SHUTDOWN   )|\
							(1<<DEI_RS_EVT_RUNTIME_EXPIRED        )|\
	                    	(1<<DEI_RS_EVT_HOOD                   )|\
							(1<<DEI_RS_EVT_BRAKE                  )|\
							(1<<DEI_RS_EVT_NEUTRAL                )|\
                        	(1<<DEI_RS_EVT_HANDBRAKE              )|\
							(1<<DEI_RS_EVT_TRIGGER                )|\
							(1<<DEI_RS_EVT_LOW_BATT               )|\
							(1<<DEI_RS_EVT_LOW_TACH               )|\
							(1<<DEI_RS_EVT_OVERREV                )|\
                            (1<<DEI_RS_EVT_MTS_LOCK_SHUTDOWN      )

	UInt8 evt ;	

//	if( brand_id != BRAND_VP_SC )
//		// send C2 feedback
//		notify_send( NOTIFY_RS_START );
	
	switch( evt = dei_rs_evt_wait( EVT_MSK_RUNTIME , 0) )
	{
		case DEI_RS_EVT_LOW_BATT :
		case DEI_RS_EVT_LOW_TACH :
		case DEI_RS_EVT_OVERREV  :
		{			
			set_rs_error_shutdown( evt );

			dei_rs_retry();
		}
		break;

		default :
		{			
			set_rs_error_shutdown( evt );
			
			dei_rs_shutdown();
		}
		break;
	}
	
	#undef EVT_MSK_RUNTIME		
}

